/bin/bash -lc "cat > /workspace/openai_client.py <<'EOF'
\"\"\"Minimal OpenAI Responses API client built on the Python standard library.

The API key is read from the "'``OPENAI_API_KEY`` environment variable by default
and is never logged, printed, or written to disk by this module.

Example::

    from openai_client import OpenAIClient

    client = OpenAIClient()
    print(client.ask("Summarize the plot of Hamlet in one sentence."))

Command line::

    python3 openai_client.py "Summarize the plot of Hamlet in one sentence."
    echo "prompt text" | python3 openai_client.py
"""

from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4.1-mini"
DEFAULT_TIMEOUT = 60.0


class OpenAIError(Exception):
    """Raised when the API returns an error or the request cannot be completed."""

    def __init__(self, message: str, status: int | None = None, body: Any = None):
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    """Tiny client for ``POST /v1/responses``."""

    def __init__(
        self,
        api_key: str | None = None,
        model: str = DEFAULT_MODEL,
        base_url: str = DEFAULT_BASE_URL,
        timeout: float = DEFAULT_TIMEOUT,
    ):
        key = api_key or os.environ.get("OPENAI_API_KEY")
        if not key:
            raise OpenAIError(
                "No API key provided. Pass api_key= or set the OPENAI_API_KEY "
                "environment variable."
            )
        self._api_key = key
        self.model = model
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def __repr__(self) -> str:
        return f"OpenAIClient(model={self.model!r}, base_url={self.base_url!r})"

    def create_response(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        store: bool = False,
        **extra: Any,
    ) -> dict[str, Any]:
        """Send ``prompt`` to the Responses API and return the parsed JSON body.

        ``store`` defaults to ``False`` so prompts are not retained by OpenAI
        for later retrieval. Extra keyword arguments (``temperature``,
        ``max_output_tokens``, ...) are passed through to the API unchanged.
        """
        payload: dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
            "store": store,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        payload.update(extra)
        return self._post("/responses", payload)

    def ask(self, prompt: str, **kwargs: Any) -> str:
        """Send ``prompt`` and return the concatenated output text."""
        return extract_text(self.create_response(prompt, **kwargs))

    def _post(self, path: str, payload: dict[str, Any]) -> dict[str, Any]:
        data = json.dumps(payload).encode("utf-8")
        request = urllib.request.Request(
            self.base_url + path,
            data=data,
            method="POST",
            headers={
                "Authorization": f"Bearer {self._api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            raw = exc.read().decode("utf-8", errors="replace")
            try:
                body: Any = json.loads(raw)
                message = body.get("error", {}).get("message", raw)
            except ValueError:
                body, message = raw, raw
            raise OpenAIError(f"HTTP {exc.code}: {message}", exc.code, body) from None
        except urllib.error.URLError as exc:
            raise OpenAIError(f"Request failed: {exc.reason}") from None


def extract_text(response: dict[str, Any]) -> str:
    """Pull the plain text out of a Responses API result."""
    if isinstance(response.get("output_text"), str):
        return response["output_text"]
    parts: list[str] = []
    for item in response.get("output", []):
        if item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                parts.append(content.get("text", ""))
    return "".join(parts)


def _main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Send a prompt to the OpenAI Responses API."
    )
    parser.add_argument("prompt", nargs="?", help="prompt text (reads stdin if omitted)")
    parser.add_argument("-m", "--model", default=DEFAULT_MODEL)
    parser.add_argument("-i", "--instructions", help="system/developer instructions")
    parser.add_argument("--json", action="store_true", help="print the raw JSON response")
    args = parser.parse_args(argv)

    prompt = args.prompt if args.prompt is not None else sys.stdin.read()
    if not prompt.strip():
        parser.error("empty prompt")

    try:
        client = OpenAIClient(model=args.model)
        if args.json:
            result = client.create_response(prompt, instructions=args.instructions)
            print(json.dumps(result, indent=2))
        else:
            print(client.ask(prompt, instructions=args.instructions))
    except OpenAIError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(_main())
